package gsurideshare_backend.controller;
import gsurideshare_backend.model.*;import gsurideshare_backend.repository.*;import gsurideshare_backend.service.CurrentUser;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/v1/requests") public class RideRequestController{
 private final RideRequestRepository requests;private final RideRepository rides;private final CurrentUser current;
 public RideRequestController(RideRequestRepository q,RideRepository r,CurrentUser c){requests=q;rides=r;current=c;}
 @GetMapping("/mine") public List<RideController.RequestView> mine(){return requests.findByPassengerIdOrderByCreatedAtDesc(current.get().getId()).stream().map(RideController::requestView).toList();}
 @PostMapping("/{id}/accept") @Transactional public RideController.RequestView accept(@PathVariable UUID id){RideRequest q=find(id);owner(q.getRide());if(q.getStatus()!=RequestStatus.PENDING)throw new IllegalStateException("Request is not pending");Ride r=rides.findLocked(q.getRide().getId()).orElseThrow(()->new NoSuchElementException("Ride not found"));if(r.getStatus()!=RideStatus.OPEN||r.getAvailableSeats()<q.getSeatsRequested())throw new IllegalStateException("Not enough seats available");r.setAvailableSeats(r.getAvailableSeats()-q.getSeatsRequested());if(r.getAvailableSeats()==0)r.setStatus(RideStatus.FULL);rides.save(r);q.setStatus(RequestStatus.ACCEPTED);return RideController.requestView(requests.save(q));}
 @PostMapping("/{id}/decline") @Transactional public RideController.RequestView decline(@PathVariable UUID id){RideRequest q=find(id);owner(q.getRide());if(q.getStatus()!=RequestStatus.PENDING)throw new IllegalStateException("Request is not pending");q.setStatus(RequestStatus.DECLINED);return RideController.requestView(requests.save(q));}
 @PostMapping("/{id}/cancel") @Transactional public RideController.RequestView cancel(@PathVariable UUID id){RideRequest q=find(id);if(!q.getPassenger().getId().equals(current.get().getId()))throw new IllegalArgumentException("Only the passenger can cancel");if(q.getStatus()!=RequestStatus.PENDING&&q.getStatus()!=RequestStatus.ACCEPTED)throw new IllegalStateException("Request cannot be cancelled");if(q.getStatus()==RequestStatus.ACCEPTED){Ride r=rides.findLocked(q.getRide().getId()).orElseThrow(()->new NoSuchElementException("Ride not found"));r.setAvailableSeats(r.getAvailableSeats()+q.getSeatsRequested());if(r.getStatus()==RideStatus.FULL)r.setStatus(RideStatus.OPEN);rides.save(r);}q.setStatus(RequestStatus.CANCELLED);return RideController.requestView(requests.save(q));}
 private RideRequest find(UUID id){return requests.findById(id).orElseThrow(()->new NoSuchElementException("Request not found"));}
 private void owner(Ride r){if(!r.getDriver().getId().equals(current.get().getId()))throw new IllegalArgumentException("Only this ride's driver can do that");}
}
